INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷107·王章传·财政措施", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/jiuwudaishi-107-wang-zhang-finance/source.txt", "note": "《旧五代史》卷107·王章传·财政措施，段落 jiu-wudaishi-205deb4a7860-p002565；已核上下文及传主，纸本及异文待核。", "id": "28b48548-706a-56be-943c-754ba502f143"}, {"title": "资治通鉴·卷289·乾祐三年·丙子诛杀与密诏", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/tongjian-289-950-assassination-orders/source.txt", "note": "《资治通鉴》卷289·乾祐三年·丙子诛杀与密诏，段落 zizhi-tongjian-a63549944a71-p003432；已核上下文及传主，纸本及异文待核。", "id": "1435cca5-da95-5076-888b-66438fc4f97c"}, {"title": "资治通鉴·卷289·乾祐三年·诛杀计划及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/tongjian-289-950-ministers-conspiracy/source.txt", "note": "《资治通鉴》卷289·乾祐三年·诛杀计划及追述，段落 zizhi-tongjian-a63549944a71-p003431；已核上下文及传主，纸本及异文待核。", "id": "8ed6223b-1852-5787-b0b5-873724b52a7a"}, {"title": "新五代史·卷10·汉本纪·乾祐三年十一月", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/16c0f5a86200a69c1b027a44e1cd6ceca86246f5/content/books/zizhi-tongjian/vol-289/year-0950/part-07/sources/library/xinwudaishi-010-han-court-killings/source.txt", "note": "《新五代史》卷10·汉本纪·乾祐三年十一月，段落 xin-wudaishi-b08f244b9241-p000353；已核上下文及传主，纸本及异文待核。", "id": "6d0ba205-beb0-5b8b-a95a-2d1e8dbe90d2"}, {"title": "资治通鉴·卷289·乾祐三年·十月至十一月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/197cc3dbf958eccdbfaf129b605c39322b104431/content/books/zizhi-tongjian/vol-289/year-0950/part-06/sources/library/tongjian-289-950-november-start/source.txt", "note": "《资治通鉴》卷289·乾祐三年·十月至十一月，段落 zizhi-tongjian-a63549944a71-p003430；已核上下文及传主，纸本及异文待核。", "id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/197cc3dbf958eccdbfaf129b605c39322b104431/content/books/zizhi-tongjian/vol-289/year-0950/part-06/sources/library/jiuwudaishi-103-november-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年十一月，段落 jiu-wudaishi-205deb4a7860-p002494；已核上下文及传主，纸本及异文待核。", "id": "2c328b83-7f54-5ad7-a5d0-94c2ddc5e2b2"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf28044c4a9f9f68546150cdc9ab0e618a0e3541/content/books/zizhi-tongjian/vol-289/year-0950/part-05/sources/library/jiuwudaishi-103-october-950/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年十月，段落 jiu-wudaishi-205deb4a7860-p002493；已核上下文及传主，纸本及异文待核。", "id": "0f47a23d-13f3-5185-a0cc-ceb3e462e903"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "王令温", "aliases": ["王令溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州河间人，后晋永清军节度使。免除邵珂军职，入朝时将其子邵崇范带在身边作人质。贝州陷落后家属被契丹俘获，944年正月被调为邓州节度使。生卒年本批未录。", "biography": null, "status": "draft", "id": "86d0426b-7115-5ca5-8f2c-358de92831a5"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "李业", "aliases": ["李業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，任武德使，刘知远时掌内库，刘承祐即位后受到宠信。950年与刘承祐等策划诛杀杨邠等大臣。出生与死亡年本批未录。", "biography": null, "status": "draft", "id": "0a670b8c-fe4d-5003-96e0-ac1c6b99b1a0"}, {"name": "阎晋卿", "aliases": ["閻晉卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "忻州人，后汉客省使。949年正月河中军夜袭后汉营寨时，提醒将士可以凭黄纸甲在火光下辨认敌军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "cd541c62-d1b8-5017-afb5-ae81ba6585ac"}, {"name": "聂文进", "aliases": ["聶文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州人，后汉枢密承旨，受到刘承祐宠信。950年参与诛杀大臣的谋划，在杨邠等被杀后召朝臣宣布其谋反。生卒年本批未录。", "biography": null, "status": "draft", "id": "947b3f67-2a3c-5318-b225-a83d6b5a9767"}, {"name": "后匡赞", "aliases": ["后赞", "後贊", "後匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瑕丘人，后汉飞龙使。949年条下与郭允明一起见于刘承祐近臣的记载。《旧五代史》写后赞，官职及朝廷人物背景相合，本批保留这个异名。生卒年尚未录入。", "biography": null, "status": "draft", "id": "ad25a35f-89f7-538f-8c83-ffe2d366f2ff"}, {"name": "郭允明", "aliases": ["窦十", "竇十"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原、河东人，小名窦十。曾在刘知远身边服役，后来担任翰林茶酒使兼鞍辔库使。949年为刘承祐近臣，《通鉴》和《旧五代史》都记其受宠。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3bedf030-0a2d-5884-8dd9-eec11a8c4ccc"}, {"name": "刘铢", "aliases": ["劉銖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "陕地人，任河东左都押牙。947年刘知远任命他为河阳节度使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "bcd8da9c-9e21-53c2-a6be-7a6d37b61a32"}, {"name": "耿氏（刘承祐宠妃）", "aliases": ["耿夫人"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "受到后汉刘承祐宠爱的耿夫人。刘承祐想立她为皇后，杨邠认为过急；她死后，刘承祐想按皇后礼安葬，杨邠又反对。姓名、生卒年及正式册立结果未载。", "biography": null, "status": "draft", "id": "62b0e085-b907-5755-bf9c-d8021f35ca71"}, {"name": "苏逢吉", "aliases": ["蘇逢吉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "长安人，任河东节度判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "1136d429-42fd-5166-94a0-f2dd9af9c920"}, {"name": "孟业", "aliases": ["孟業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉供奉官。950年奉刘承祐命携带密诏前往澶州和邺都，传达杀王殷、郭威及王峻等人的命令。生卒年未载。", "biography": null, "status": "draft", "id": "cd735167-b0f8-5ed8-a58c-17e706c26246"}, {"name": "李洪义", "aliases": ["李洪義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉李太后的弟弟，950年任镇宁节度使。刘承祐下密诏令他杀驻澶州的王殷，本段只记命令，未记他已经执行。生卒年未载。", "biography": null, "status": "draft", "id": "12dc9c88-13ce-589c-94c7-384ae0bd7223"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "郭崇威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "应州马军都指挥使，金城人。937年条中记载他不愿臣服契丹，独自南归。", "biography": null, "status": "draft", "id": "2f1d1823-9873-5df8-83ed-7330578213e6"}, {"name": "曹威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，950年任邺都行营步军都指挥使。刘承祐密令他与郭崇威杀郭威及监军王峻，本段尚未记实际执行。生卒年未载。", "biography": null, "status": "draft", "id": "c26ccc4f-2658-5be8-b917-885c6c56f287"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "薛怀让", "aliases": ["薛懷讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋怀州刺史。944年二月乙巳与李守贞、皇甫遇、梁汉璋等率合计一万军队沿河水陆进兵。生卒年本批未核。", "biography": null, "status": "draft", "id": "f1bb0fbd-9418-522b-b292-28446544ad7f"}, {"name": "吴虔裕", "aliases": ["吳虔裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉河中行营都监。949年四月奉郭威之命，率兵从侧面攻击李守贞出城部队，击败对方并夺取攻城器具。生卒年尚未确定。", "biography": null, "status": "draft", "id": "e576a210-c5b6-5c62-8309-4f25ed7f2693"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "李洪建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李业的兄长，950年任侍卫马军都指挥使，后暂判侍卫司相关事务。收到杀王殷家属的命令后，只派人看守并继续供给饮食。生卒年未载。", "biography": null, "status": "draft", "id": "20743d65-b3c4-5fd8-a598-3fa66314e4bc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
