SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "后汉拟派王令温救潭州，因内乱未能出兵。", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p043·原文件第48行", "note": "原文：朝廷议发兵，以安远节度使王令温为都部署，以救潭州，会内难作，不果。；核对说明：以为都部署与救潭州计划关联，内难导致不果，不写成军队已抵潭州。", "status": "draft", "id": "d4ab6c42-6ef7-5215-8afb-fedb75fbb558", "subject_id": "a15dc734-94de-5b0f-9633-09917854a7e9", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十一月条下，诛杀大臣的内乱前后，具体议兵日未载", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p043·原文件第48行", "note": "原文：朝廷议发兵，以安远节度使王令温为都部署，以救潭州，会内难作，不果。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "7c258fe9-66ed-5e83-aefb-45e1403b619b", "subject_id": "a15dc734-94de-5b0f-9633-09917854a7e9", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘承祐：朝廷在其统治下筹议援楚。", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p043·原文件第48行", "note": "原文：朝廷议发兵，以安远节度使王令温为都部署，以救潭州，会内难作，不果。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "13ebc735-82e2-5d8f-bb49-b71df21c76c6", "subject_id": "96b54cac-772d-54e8-b2de-975b3be49e85", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘承祐：朝廷在其统治下筹议援楚。", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p043·原文件第48行", "note": "原文：朝廷议发兵，以安远节度使王令温为都部署，以救潭州，会内难作，不果。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "bbd3658c-5062-56cd-999f-71017aa70579", "subject_id": "5c9239ee-fa84-56f2-8224-6cc6c00a6b4e", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "person", "field_path": "description", "claim_text": "王令温：拟任援潭州军都部署。", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p043·原文件第48行", "note": "原文：朝廷议发兵，以安远节度使王令温为都部署，以救潭州，会内难作，不果。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "79baba50-c204-5115-9d8a-723b972a978e", "subject_id": "86d0426b-7115-5ca5-8f2c-358de92831a5", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王令温：拟任援潭州军都部署。", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p043·原文件第48行", "note": "原文：朝廷议发兵，以安远节度使王令温为都部署，以救潭州，会内难作，不果。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "69f08caf-8cf1-5571-84fc-73818a48826d", "subject_id": "ae91c885-efb8-5b90-ad7d-e4f82a9ef0cb", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记朝廷议兵援助湖南，遇内乱未成行。", "citation": "《旧五代史》卷103·隐帝本纪·乾祐三年十月，段落 jiu-wudaishi-205deb4a7860-p002493；已核上下文及传主，纸本及异文待核。", "note": "原文：時朝廷方議起軍，會內難，不果行。；核对说明：在十月求援之后补述结果，没有王令温姓名；不能作为其任命的独立确证。", "status": "draft", "id": "3d3be701-7315-509c-b3f3-d35826d9e3bf", "subject_id": "a15dc734-94de-5b0f-9633-09917854a7e9", "source_id": "0f47a23d-13f3-5185-a0cc-ceb3e462e903"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘承祐即位后，杨邠、郭威、史弘肇和王章分掌要务。", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p044·原文件第49行", "note": "原文：帝自即位以来，枢密使、右仆射、同平章事杨邠总机政，枢密使兼侍中郭威主征伐，归德节度使、侍卫亲军都指挥使兼中书令史弘肇典宿卫，三司使、同平章事王章掌财赋。；核对说明：这是即位以来职掌概述，不造950年十一月四人同时初次任命。", "status": "draft", "id": "acdceda3-8945-5495-9d91-ca49a69ebd7c", "subject_id": "c1a4f6a4-2bc4-5151-9832-af3190e4892d", "source_id": "4b39840e-e485-5868-9dfa-f71caf108fe5"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "刘承祐即位后至950年十一月之前的追述，具体发生年月未载", "citation": "卷289·乾祐三年（950年十一月及此前追述）·zztj-v289-y0950-p044·原文件第49行", "note": "原文：帝自即位以来，枢密使、右仆射、同平章事杨邠总机政，枢密使兼侍中郭威主征伐，归德节度使、侍卫亲军都指挥使兼中书令史弘肇典宿卫，三司使、同平章事王章掌财赋。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "df91f244-7c0d-522a-9f1d-3350b09614af", "subject_id": "c1a4f6a4-2bc4-5151-9832-af3190e4892d", "source_id": "4b39840e-e485